declarations.source:
[
  Jido.Action,
  [
    name: "retrieval_recall_memory",
    description: "Recall memory snippets relevant to a query",
    schema:
      Zoi.object(%{
        query: Zoi.string(description: "Recall query text"),
        top_k: Zoi.integer(description: "Number of memory snippets to return") |> Zoi.default(3),
        namespace: Zoi.string(description: "Memory namespace") |> Zoi.optional()
      })
  ]
]

[
  Jido.Action,
  [
    name: "retrieval_upsert_memory",
    description: "Insert or update retrieval memory",
    schema:
      Zoi.object(%{
        id: Zoi.string(description: "Memory ID") |> Zoi.optional(),
        text: Zoi.string(description: "Memory text content"),
        metadata: Zoi.map(description: "Optional memory metadata") |> Zoi.default(%{}),
        namespace: Zoi.string(description: "Memory namespace") |> Zoi.optional()
      })
  ]
]

[
  [
    mode: :allow_list,
    allow: MapSet.new(@default_allowed),
    deny: MapSet.new(@default_denied),
    constraints: %{}
  ]
]

[
  Jido.Action,
  [
    name: "ai_request_cancel",
    schema:
      Zoi.object(%{
        request_id: Zoi.string() |> Zoi.nullable() |> Zoi.default(nil),
        reason: Zoi.any() |> Zoi.default(nil)
      })
  ]
]

[
  transform_request(request(), State.t(), Config.t(), map()) ::
    {:ok, overrides()} | {:error, term()}
]

[
  Jido.Signal,
  [
    type: "ai.request.started",
    default_source: "/ai/request",
    schema:
      Zoi.object(
        %{
          request_id: Zoi.string(),
          query: Jido.AI.Query.schema(),
          run_id: Zoi.string() |> Zoi.optional()
        },
        unrecognized_keys: :error
      )
  ]
]
